$(function(){$("form[data-form-role='addtocart']").on("nwazet.productunavailable",function(){$(this).find('[type="submit"]').prop("disabled",!0);var n=$(this).find(".addtocart-quantity-and-button");n.length&&n.hide()}).on("nwazet.productavailable",function(){var n=$(this).find(".addtocart-quantity-and-button");n.length&&n.show()});$("form[data-form-role='addtocart']").each(function(n,t){var i=$(t).find("[data-product-unavailable]");i.length?$(t).trigger("nwazet.productunavailable"):$(t).trigger("nwazet.productavailable")})});